  1→import type {
  2→	DimensionAnalysisInput,
  3→	SessionAnalytics,
  4→	SessionAnalyticsSummary as SessionAnalyticsSummaryBase,
  5→	SessionDetail,
  6→} from "@rudel/api-routes";
  7→import {
  8→	addOptionalStringEqFilter,
  9→	buildDateFilter,
 10→	queryClickhouse,
 11→} from "../clickhouse.js";
 12→
 13→export interface SessionAnalyticsRaw {
 14→	session_id: string;
 15→	user_id: string;
 16→	session_date: string;
 17→	project_path: string;
 18→	organization_id: string;
 19→	git_remote: string;
 20→	package_name: string;
 21→
 22→	// Interaction timing metrics
 23→	total_interactions: number;
 24→	avg_period_sec: number;
 25→	median_period_sec: number;
 26→	quick_responses: number;
 27→	normal_responses: number;
 28→	long_pauses: number;
 29→	actual_duration_min: number;
 30→
 31→	// Duration metrics
 32→	last_interaction_date: string;
 33→
 34→	// Token metrics
 35→	total_tokens: number;
 36→	input_tokens: number;
 37→	output_tokens: number;
 38→
 39→	// Git activity
 40→	git_sha: string;
 41→	git_branch: string;
 42→	has_commit: number;
 43→
 44→	// Feature arrays
 45→	subagent_types: string[];
 46→	skills: string[];
 47→	slash_commands: string[];
 48→
 49→	// Success metrics
 50→	session_archetype: string;
 51→	success_score: number;
 52→
 53→	// Effectiveness correlation factors
 54→	error_count: number;
 55→	model_used: string;
 56→	used_plan_mode: number;
 57→}
 58→
 59→export interface SessionAnalyticsSummary extends SessionAnalyticsSummaryBase {
 60→	total_interactions: number;
 61→	avg_interactions_per_session: number;
 62→	median_response_time_sec: number;
 63→	quick_response_rate: number;
 64→	long_pause_rate: number;
 65→}
 66→
 67→/**
 68→ * Get session analytics from the materialized view
 69→ */
 70→export async function getSessionAnalytics(
 71→	orgId: string,
 72→	params: {
 73→		days?: number;
 74→		user_id?: string;
 75→		project_path?: string;
 76→		repository?: string;
 77→		limit?: number;
 78→		offset?: number;
 79→		sort_by?: "date" | "duration" | "interactions";
 80→		sort_order?: "asc" | "desc";
 81→	} = {},
 82→): Promise<SessionAnalytics[]> {
 83→	const {
 84→		days = 30,
 85→		user_id,
 86→		project_path,
 87→		repository,
 88→		limit = 50,
 89→		offset = 0,
 90→		sort_by = "date",
 91→		sort_order = "desc",
 92→	} = params;
 93→
 94→	const d = Number(days);
 95→	const query_params: Record<string, unknown> = {
 96→		days: d,
 97→		limit: Number(limit),
 98→		offset: Number(offset),
 99→		orgId,
100→	};
101→	const filters: string[] = [];
102→	addOptionalStringEqFilter(
103→		filters,
104→		query_params,
105→		"user_id",
106→		"userId",
107→		user_id,
108→	);
109→	addOptionalStringEqFilter(
110→		filters,
111→		query_params,
112→		"project_path",
113→		"projectPath",
114→		project_path,
115→	);
116→	if (repository) {
117→		filters.push(
118→			"(git_remote = {repository:String} OR package_name = {repository:String} OR project_path = {repository:String})",
119→		);
120→		query_params.repository = repository;
121→	}
122→
123→	const sortColumn =
124→		sort_by === "duration"
125→			? "actual_duration_min"
126→			: sort_by === "interactions"
127→				? "total_interactions"
128→				: "sa.session_date";
129→	const sortDirection = sort_order === "asc" ? "ASC" : "DESC";
130→
131→	const query = `
132→    SELECT
133→      session_id,
134→      user_id,
135→      formatDateTime(sa.session_date, '%Y-%m-%dT%H:%i:%SZ') as session_date,
136→      project_path,
137→      organization_id,
138→      git_remote,
139→      package_name,
140→      total_interactions,
141→      avg_period_sec,
142→      median_period_sec,
143→      quick_responses,
144→      normal_responses,
145→      long_pauses,
146→      actual_duration_min,
147→      formatDateTime(sa.last_interaction_date, '%Y-%m-%dT%H:%i:%SZ') as last_interaction_date,
148→      total_tokens,
149→      input_tokens,
150→      output_tokens,
151→      git_sha,
152→      git_branch,
153→      has_commit,
154→      subagent_types,
155→      skills,
156→      slash_commands,
157→      session_archetype,
158→      success_score,
159→      error_count,
160→      model_used,
161→      used_plan_mode
162→    FROM rudel.session_analytics sa
163→    WHERE ${buildDateFilter("days", "sa.session_date")}
164→      AND organization_id = {orgId:String}
165→      ${filters.length > 0 ? `AND ${filters.join("\n      AND ")}` : ""}
166→    ORDER BY ${sortColumn} ${sortDirection}
167→    LIMIT {limit:UInt32}
168→    OFFSET {offset:UInt32}
169→  `;
170→
171→	const raw = await queryClickhouse<SessionAnalyticsRaw>({
172→		query,
173→		query_params,
174→	});
175→
176→	return raw.map(
177→		(row): SessionAnalytics => ({
178→			session_id: row.session_id,
179→			user_id: row.user_id,
180→			session_date: row.session_date,
181→			project_path: row.project_path,
182→			repository:
183→				row.git_remote || row.package_name || row.project_path || null,
184→			git_remote: row.git_remote || undefined,
185→			duration_min: row.actual_duration_min,
186→			total_tokens: row.total_tokens,
187→			input_tokens: row.input_tokens,
188→			output_tokens: row.output_tokens,
189→			success_score: row.success_score,
190→			total_interactions: row.total_interactions,
191→			avg_period_sec: row.avg_period_sec,
192→			subagent_types: row.subagent_types,
193→			skills: row.skills,
194→			slash_commands: row.slash_commands,
195→			has_commit: row.has_commit > 0,
196→			session_archetype: row.session_archetype,
197→			model_used: row.model_used,
198→			used_plan_mode: row.used_plan_mode > 0,
199→		}),
200→	);
201→}
