203→/**
204→ * Get summary statistics from session analytics
205→ */
206→export async function getSessionAnalyticsSummary(
207→	orgId: string,
208→	params: {
209→		days?: number;
210→		user_id?: string;
211→		project_path?: string;
212→	} = {},
213→): Promise<SessionAnalyticsSummary> {
214→	const { days = 30, user_id, project_path } = params;
215→	const d = Number(days);
216→	const query_params: Record<string, unknown> = {
217→		days: d,
218→		orgId,
219→	};
220→	const filters: string[] = [];
221→	addOptionalStringEqFilter(
222→		filters,
223→		query_params,
224→		"user_id",
225→		"userId",
226→		user_id,
227→	);
228→	addOptionalStringEqFilter(
229→		filters,
230→		query_params,
231→		"project_path",
232→		"projectPath",
233→		project_path,
234→	);
235→
236→	const query = `
237→    WITH totals AS (
238→      SELECT
239→        COUNT(*) as cnt_sessions,
240→        SUM(total_interactions) as sum_interactions,
241→        SUM(quick_responses) as sum_quick_responses,
242→        SUM(long_pauses) as sum_long_pauses,
243→        ifNull(AVG(actual_duration_min), 0) as avg_duration,
244→        ifNull(AVG(total_interactions), 0) as avg_interactions,
245→        ifNull(AVG(avg_period_sec), 0) as avg_response,
246→        ifNull(AVG(median_period_sec), 0) as med_response,
247→        countIf(length(subagent_types) > 0) as cnt_subagents,
248→        countIf(length(skills) > 0) as cnt_skills,
249→        countIf(length(slash_commands) > 0) as cnt_slash
250→      FROM rudel.session_analytics
251→      WHERE ${buildDateFilter("days")}
252→        AND organization_id = {orgId:String}
253→        ${filters.length > 0 ? `AND ${filters.join("\n        AND ")}` : ""}
254→    )
255→    SELECT
256→      cnt_sessions as total_sessions,
257→      sum_interactions as total_interactions,
258→      ifNull(round(avg_duration, 2), 0) as avg_session_duration_min,
259→      ifNull(round(avg_interactions, 2), 0) as avg_interactions_per_session,
260→      ifNull(round(avg_response, 2), 0) as avg_response_time_sec,
261→      ifNull(round(med_response, 2), 0) as median_response_time_sec,
262→      round(sum_quick_responses * 100.0 / if(sum_interactions > 0, sum_interactions, 1), 2) as quick_response_rate,
263→      round(sum_long_pauses * 100.0 / if(sum_interactions > 0, sum_interactions, 1), 2) as long_pause_rate,
264→      round(cnt_subagents * 100.0 / if(cnt_sessions > 0, cnt_sessions, 1), 2) as subagents_adoption_rate,
265→      round(cnt_skills * 100.0 / if(cnt_sessions > 0, cnt_sessions, 1), 2) as skills_adoption_rate,
266→      round(cnt_slash * 100.0 / if(cnt_sessions > 0, cnt_sessions, 1), 2) as slash_commands_adoption_rate
267→    FROM totals
268→  `;
269→
270→	const results = await queryClickhouse<SessionAnalyticsSummary>({
271→		query,
272→		query_params,
273→	});
274→
275→	const defaults: SessionAnalyticsSummary = {
276→		total_sessions: 0,
277→		total_interactions: 0,
278→		avg_session_duration_min: 0,
279→		avg_interactions_per_session: 0,
280→		avg_response_time_sec: 0,
281→		median_response_time_sec: 0,
282→		quick_response_rate: 0,
283→		long_pause_rate: 0,
284→		subagents_adoption_rate: 0,
285→		skills_adoption_rate: 0,
286→		slash_commands_adoption_rate: 0,
287→	};
288→
289→	if (results.length === 0) {
290→		return defaults;
291→	}
292→
293→	// Coalesce nulls from ClickHouse (AVG on 0 rows returns null despite ifNull)
294→	const row = results[0] as Record<string, unknown> | undefined;
295→	if (!row) return defaults;
296→	return Object.fromEntries(
297→		Object.entries(defaults).map(([key, def]) => [key, row[key] ?? def]),
298→	) as SessionAnalyticsSummary;
299→}
