301→export type SessionSummaryComparisonPeriod = SessionAnalyticsSummaryBase;
302→
303→/**
304→ * Get session analytics summary with period-over-period comparison
305→ */
306→export async function getSessionAnalyticsSummaryComparison(
307→	orgId: string,
308→	params: {
309→		days?: number;
310→		user_id?: string;
311→		project_path?: string;
312→	} = {},
313→) {
314→	const { days = 7, user_id, project_path } = params;
315→	const d = Number(days);
316→	const previousDays = d * 2;
317→	const baseParams: Record<string, unknown> = {
318→		currentDays: d,
319→		previousDays,
320→		orgId,
321→	};
322→	const filters: string[] = [];
323→	addOptionalStringEqFilter(filters, baseParams, "user_id", "userId", user_id);
324→	addOptionalStringEqFilter(
325→		filters,
326→		baseParams,
327→		"project_path",
328→		"projectPath",
329→		project_path,
330→	);
331→
332→	const summarySQL = (dateCondition: string) => `
333→    WITH totals AS (
334→      SELECT
335→        COUNT(*) as cnt_sessions,
336→        ifNull(AVG(actual_duration_min), 0) as avg_duration,
337→        ifNull(AVG(avg_period_sec), 0) as avg_response,
338→        countIf(length(subagent_types) > 0) as cnt_subagents,
339→        countIf(length(skills) > 0) as cnt_skills,
340→        countIf(length(slash_commands) > 0) as cnt_slash
341→      FROM rudel.session_analytics
342→      WHERE ${dateCondition}
343→        AND organization_id = {orgId:String}
344→        ${filters.length > 0 ? `AND ${filters.join("\n        AND ")}` : ""}
345→    )
346→    SELECT
347→      cnt_sessions as total_sessions,
348→      ifNull(round(avg_duration, 2), 0) as avg_session_duration_min,
349→      ifNull(round(avg_response, 2), 0) as avg_response_time_sec,
350→      round(cnt_subagents * 100.0 / if(cnt_sessions > 0, cnt_sessions, 1), 2) as subagents_adoption_rate,
351→      round(cnt_skills * 100.0 / if(cnt_sessions > 0, cnt_sessions, 1), 2) as skills_adoption_rate,
352→      round(cnt_slash * 100.0 / if(cnt_sessions > 0, cnt_sessions, 1), 2) as slash_commands_adoption_rate
353→    FROM totals
354→  `;
355→
356→	const currentQuery = summarySQL(buildDateFilter("currentDays"));
357→	const previousQuery = summarySQL(
358→		"session_date >= now64(3) - toIntervalDay({previousDays:UInt32}) AND session_date < now64(3) - toIntervalDay({currentDays:UInt32})",
359→	);
360→
361→	const [currentData, previousData] = await Promise.all([
362→		queryClickhouse<SessionSummaryComparisonPeriod>({
363→			query: currentQuery,
364→			query_params: baseParams,
365→		}),
366→		queryClickhouse<SessionSummaryComparisonPeriod>({
367→			query: previousQuery,
368→			query_params: baseParams,
369→		}),
370→	]);
371→
372→	const defaultPeriod: SessionSummaryComparisonPeriod = {
373→		total_sessions: 0,
374→		avg_session_duration_min: 0,
375→		avg_response_time_sec: 0,
376→		subagents_adoption_rate: 0,
377→		skills_adoption_rate: 0,
378→		slash_commands_adoption_rate: 0,
379→	};
380→
381→	// Coalesce nulls from ClickHouse (AVG on 0 rows returns null despite ifNull)
382→	const coalesce = (
383→		row: SessionSummaryComparisonPeriod | undefined,
384→	): SessionSummaryComparisonPeriod => {
385→		if (!row) return { ...defaultPeriod };
386→		return Object.fromEntries(
387→			Object.entries(defaultPeriod).map(([key, def]) => [
388→				key,
389→				(row as unknown as Record<string, unknown>)[key] ?? def,
390→			]),
391→		) as SessionSummaryComparisonPeriod;
392→	};
393→	const current = coalesce(currentData[0]);
394→	const previous = coalesce(previousData[0]);
395→
396→	const calculateChange = (curr: number, prev: number) => {
397→		if (!prev || prev === 0) return 0;
398→		return ((curr - prev) / prev) * 100;
399→	};
400→
401→	const changes = {
402→		total_sessions: calculateChange(
403→			current.total_sessions || 0,
404→			previous.total_sessions || 0,
405→		),
406→		avg_session_duration_min: calculateChange(
407→			current.avg_session_duration_min || 0,
408→			previous.avg_session_duration_min || 0,
409→		),
410→		avg_response_time_sec: calculateChange(
411→			current.avg_response_time_sec || 0,
412→			previous.avg_response_time_sec || 0,
413→		),
414→	};
415→
416→	return { current, previous, changes };
417→}
