419→/**
420→ * Get interaction timing distribution
421→ */
422→export async function getInteractionTimingDistribution(
423→	orgId: string,
424→	params: {
425→		days?: number;
426→		user_id?: string;
427→		project_path?: string;
428→	} = {},
429→): Promise<Array<{ bucket: string; count: number; percentage: number }>> {
430→	const { days = 30, user_id, project_path } = params;
431→	const d = Number(days);
432→	const query_params: Record<string, unknown> = {
433→		days: d,
434→		orgId,
435→	};
436→	const filters: string[] = [];
437→	addOptionalStringEqFilter(
438→		filters,
439→		query_params,
440→		"user_id",
441→		"userId",
442→		user_id,
443→	);
444→	addOptionalStringEqFilter(
445→		filters,
446→		query_params,
447→		"project_path",
448→		"projectPath",
449→		project_path,
450→	);
451→	const filterSql =
452→		filters.length > 0 ? `AND ${filters.join("\n        AND ")}` : "";
453→	const repeatedFilterSql =
454→		filters.length > 0 ? `AND ${filters.join("\n      AND ")}` : "";
455→
456→	const query = `
457→    WITH total AS (
458→      SELECT SUM(total_interactions) as total_count
459→      FROM rudel.session_analytics
460→      WHERE ${buildDateFilter("days")}
461→        AND organization_id = {orgId:String}
462→        ${filterSql}
463→    )
464→    SELECT
465→      'Instant (< 5s)' as bucket,
466→      SUM(quick_responses) as count,
467→      round(SUM(quick_responses) * 100.0 / (SELECT total_count FROM total), 2) as percentage
468→    FROM rudel.session_analytics
469→    WHERE ${buildDateFilter("days")}
470→      AND organization_id = {orgId:String}
471→      ${repeatedFilterSql}
472→
473→    UNION ALL
474→
475→    SELECT
476→      'Normal (5-60s)' as bucket,
477→      SUM(normal_responses) as count,
478→      round(SUM(normal_responses) * 100.0 / (SELECT total_count FROM total), 2) as percentage
479→    FROM rudel.session_analytics
480→    WHERE ${buildDateFilter("days")}
481→      AND organization_id = {orgId:String}
482→      ${repeatedFilterSql}
483→
484→    UNION ALL
485→
486→    SELECT
487→      'Long Pause (> 5m)' as bucket,
488→      SUM(long_pauses) as count,
489→      round(SUM(long_pauses) * 100.0 / (SELECT total_count FROM total), 2) as percentage
490→    FROM rudel.session_analytics
491→    WHERE ${buildDateFilter("days")}
492→      AND organization_id = {orgId:String}
493→      ${repeatedFilterSql}
494→
495→    ORDER BY count DESC
496→  `;
497→
498→	return queryClickhouse<{ bucket: string; count: number; percentage: number }>(
499→		{
500→			query,
501→			query_params,
502→		},
503→	);
504→}
