506→/**
507→ * Get flexible dimension analysis with optional split-by for stacked charts
508→ */
509→
510→// Map metric to SQL expression
511→const METRIC_EXPRESSIONS: Record<DimensionAnalysisInput["metric"], string> = {
512→	session_count: "COUNT(*)",
513→	avg_duration: "round(AVG(actual_duration_min), 2)",
514→	total_duration: "round(SUM(actual_duration_min) / 60, 2)",
515→	avg_interactions: "round(AVG(total_interactions), 2)",
516→	total_interactions: "SUM(total_interactions)",
517→	avg_response_time: "round(AVG(avg_period_sec), 2)",
518→	median_response_time: "round(AVG(median_period_sec), 2)",
519→	avg_tokens: "round(AVG(total_tokens), 0)",
520→	total_tokens: "SUM(total_tokens)",
521→	avg_success_score: "round(AVG(success_score), 2)",
522→	avg_errors: "round(AVG(error_count), 2)",
523→	total_errors: "SUM(error_count)",
524→};
525→
526→const DIMENSION_EXPRESSIONS: Record<
527→	DimensionAnalysisInput["dimension"],
528→	string
529→> = {
530→	user_id: "user_id",
531→	project_path: "arrayElement(splitByChar('/', project_path), -1)",
532→	repository:
533→		"if(git_remote != '', git_remote, if(package_name != '', package_name, project_path))",
534→	session_archetype: "session_archetype",
535→	model_used: "model_used",
536→	has_commit: "has_commit",
537→	used_plan_mode: "used_plan_mode",
538→	used_skills: "if(length(skills) > 0, 1, 0)",
539→	used_slash_commands: "if(length(slash_commands) > 0, 1, 0)",
540→	used_subagents: "if(length(subagent_types) > 0, 1, 0)",
541→};
542→
543→export async function getSessionDimensionAnalysis(
544→	orgId: string,
545→	params: {
546→		days?: number;
547→		dimension: DimensionAnalysisInput["dimension"];
548→		metric: DimensionAnalysisInput["metric"];
549→		split_by?: DimensionAnalysisInput["dimension"];
550→		limit?: number;
551→		user_id?: string;
552→		project_path?: string;
553→	},
554→) {
555→	const {
556→		days = 7,
557→		dimension,
558→		metric,
559→		split_by,
560→		limit = 10,
561→		user_id,
562→		project_path,
563→	} = params;
564→	const d = Number(days);
565→	const query_params: Record<string, unknown> = {
566→		days: d,
567→		limit: Number(limit),
568→		orgId,
569→	};
570→
571→	const metricExpression = METRIC_EXPRESSIONS[metric];
572→	const dimensionExpression = DIMENSION_EXPRESSIONS[dimension];
573→	const splitByExpression = split_by ? DIMENSION_EXPRESSIONS[split_by] : null;
574→
575→	const filters: string[] = [];
576→	addOptionalStringEqFilter(
577→		filters,
578→		query_params,
579→		"user_id",
580→		"userId",
581→		user_id,
582→	);
583→	addOptionalStringEqFilter(
584→		filters,
585→		query_params,
586→		"project_path",
587→		"projectPath",
588→		project_path,
589→	);
590→
591→	let query: string;
592→
593→	if (split_by) {
594→		query = `
595→      SELECT
596→        ${dimensionExpression} as dimension_value,
597→        ${splitByExpression} as split_value,
598→        ${metricExpression} as metric_value
599→      FROM rudel.session_analytics
600→      WHERE ${buildDateFilter("days")}
601→        AND organization_id = {orgId:String}
602→        ${filters.length > 0 ? `AND ${filters.join("\n        AND ")}` : ""}
603→      GROUP BY dimension_value, split_value
604→      ORDER BY metric_value DESC
605→    `;
606→	} else {
607→		query = `
608→      SELECT
609→        ${dimensionExpression} as dimension_value,
610→        ${metricExpression} as metric_value
611→      FROM rudel.session_analytics
612→      WHERE ${buildDateFilter("days")}
613→        AND organization_id = {orgId:String}
614→        ${filters.length > 0 ? `AND ${filters.join("\n        AND ")}` : ""}
615→      GROUP BY dimension_value
616→      ORDER BY metric_value DESC
617→      LIMIT {limit:UInt32}
618→    `;
619→	}
620→
621→	interface DimensionRow {
622→		dimension_value: string;
623→		split_value?: string;
624→		metric_value: number;
625→	}
626→
627→	const results = await queryClickhouse<DimensionRow>({
628→		query,
629→		query_params,
630→	});
631→
632→	if (split_by) {
633→		const grouped = new Map<string, Record<string, number>>();
634→		const totalMetric = new Map<string, number>();
635→
636→		for (const row of results) {
637→			const dimVal = String(row.dimension_value);
638→			const splitVal = String(row.split_value);
639→			const metricVal = Number(row.metric_value);
640→
641→			if (!grouped.has(dimVal)) {
642→				grouped.set(dimVal, {});
643→				totalMetric.set(dimVal, 0);
644→			}
645→
646→			const group = grouped.get(dimVal);
647→			if (group) group[splitVal] = metricVal;
648→			totalMetric.set(dimVal, (totalMetric.get(dimVal) || 0) + metricVal);
649→		}
650→
651→		const finalData = Array.from(grouped.entries())
652→			.map(([dimension_value, split_values]) => ({
653→				dimension_value,
654→				split_values,
655→				_total: totalMetric.get(dimension_value) || 0,
656→			}))
657→			.sort((a, b) => b._total - a._total)
658→			.slice(0, Number(limit))
659→			.map(({ dimension_value, split_values }) => ({
660→				dimension_value,
661→				split_values,
662→			}));
663→
664→		return finalData;
665→	}
666→
667→	return results.map((row) => ({
668→		dimension_value: String(row.dimension_value),
669→		metric_value: Number(row.metric_value),
670→	}));
671→}
