 19→const PROJECT_KEY_EXPR = `if(git_remote != '', git_remote, if(package_name != '', package_name, project_path))`;
 20→const PROJECT_DISPLAY_EXPR = `if(git_remote != '', arrayElement(splitByChar('/', git_remote), -1), arrayElement(splitByChar('/', replaceAll(project_path, '\\\\', '/')), -1))`;
 21→
 22→function buildProjectDisplaySubquery(
 23→	orgParamName: string,
 24→	projectParamName: string,
 25→): string {
 26→	return `(
 27→    SELECT
 28→      if(
 29→        count() > 0,
 30→        any(${PROJECT_DISPLAY_EXPR}),
 31→        if(
 32→          position({${projectParamName}:String}, '/') > 0,
 33→          arrayElement(splitByChar('/', {${projectParamName}:String}), -1),
 34→          {${projectParamName}:String}
 35→        )
 36→      ) as project_display
 37→    FROM rudel.session_analytics
 38→    WHERE organization_id = {${orgParamName}:String}
 39→      AND (
 40→        project_path = {${projectParamName}:String}
 41→        OR git_remote = {${projectParamName}:String}
 42→        OR ${PROJECT_KEY_EXPR} = {${projectParamName}:String}
 43→      )
 44→      AND (git_remote != '' OR package_name != '' OR project_path != '')
 45→  )`;
 46→}
