102→/**
103→ * Get AI investment by project - where is time being spent?
104→ */
105→export async function getProjectInvestment(
106→	orgId: string,
107→	params: {
108→		days?: number;
109→		limit?: number;
110→		offset?: number;
111→		project_path?: string;
112→		project_paths?: string[];
113→	} = {},
114→): Promise<ProjectInvestment[]> {
115→	const {
116→		days = 30,
117→		limit = 20,
118→		offset = 0,
119→		project_path,
120→		project_paths,
121→	} = params;
122→	const d = Number(days);
123→	const query_params: Record<string, unknown> = {
124→		currentDays: d,
125→		previousDays: d * 2,
126→		limit: Number(limit),
127→		offset: Number(offset),
128→		orgId,
129→	};
130→	const projectFilters: string[] = [];
131→	addOptionalStringEqFilter(
132→		projectFilters,
133→		query_params,
134→		"project_path",
135→		"projectPath",
136→		project_path,
137→	);
138→	if (!project_path) {
139→		addOptionalStringInFilter(
140→			projectFilters,
141→			query_params,
142→			"project_path",
143→			"projectPathList",
144→			project_paths,
145→		);
146→	}
147→
148→	const query = `
149→    WITH current_period AS (
150→      SELECT
151→        ${PROJECT_DISPLAY_EXPR} as project_display,
152→        any(git_remote) as _git_remote,
153→        any(project_path) as _project_path,
154→        COUNT(*) as sessions,
155→        COUNT(DISTINCT user_id) as unique_users,
156→        SUM(ifNull(input_tokens, 0)) as input_tokens_sum,
157→        SUM(ifNull(output_tokens, 0)) as output_tokens_sum,
158→        SUM(ifNull(input_tokens, 0) + ifNull(output_tokens, 0)) as total_tokens,
159→        round(SUM(actual_duration_min), 2) as total_duration_min,
160→        round(AVG(actual_duration_min), 2) as avg_session_duration_min,
161→        round(AVG(success_score), 2) as success_rate
162→      FROM rudel.session_analytics
163→      WHERE ${buildDateFilter("currentDays")}
164→        AND organization_id = {orgId:String}
165→        AND (git_remote != '' OR package_name != '' OR project_path != '')
166→        ${projectFilters.length > 0 ? `AND ${projectFilters.join("\n        AND ")}` : ""}
167→      GROUP BY ${PROJECT_DISPLAY_EXPR}
168→    ),
169→    previous_period AS (
170→      SELECT
171→        ${PROJECT_DISPLAY_EXPR} as project_display,
172→        round(AVG(success_score), 2) as prev_success_rate
173→      FROM rudel.session_analytics
174→      WHERE session_date >= now64(3) - toIntervalDay({previousDays:UInt32})
175→        AND session_date < now64(3) - toIntervalDay({currentDays:UInt32})
176→        AND organization_id = {orgId:String}
177→        AND (git_remote != '' OR package_name != '' OR project_path != '')
178→        ${projectFilters.length > 0 ? `AND ${projectFilters.join("\n        AND ")}` : ""}
179→      GROUP BY ${PROJECT_DISPLAY_EXPR}
180→    )
181→    SELECT
182→      c.project_display as repository,
183→      c._git_remote as git_remote,
184→      c._project_path as project_path,
185→      c.sessions,
186→      c.unique_users,
187→      c.total_tokens,
188→      c.input_tokens_sum as input_tokens,
189→      c.output_tokens_sum as output_tokens,
190→      c.total_duration_min,
191→      c.avg_session_duration_min,
192→      c.success_rate,
193→      round((c.output_tokens_sum / 1000000.0) * 15.0 + (c.input_tokens_sum / 1000000.0) * 3.0, 4) as cost,
194→      round(c.success_rate - ifNull(p.prev_success_rate, c.success_rate), 2) as success_rate_trend
195→    FROM current_period c
196→    LEFT JOIN previous_period p ON c.project_display = p.project_display
197→    ORDER BY c.total_duration_min DESC
198→    LIMIT {limit:UInt32}
199→    OFFSET {offset:UInt32}
200→  `;
201→
202→	const results = await queryClickhouse<
203→		ProjectInvestment & { git_remote?: string }
204→	>({
205→		query,
206→		query_params,
207→	});
208→
209→	return results.map((project) => ({
210→		...project,
211→		repository: project.repository || null,
212→		git_remote: project.git_remote || undefined,
213→	}));
214→}
