263→/**
264→ * Get project activity trend over time
265→ */
266→export async function getProjectActivity(
267→	orgId: string,
268→	projectPath: string,
269→	params: { days?: number; granularity?: "day" | "week" | "month" } = {},
270→): Promise<ProjectActivity[]> {
271→	const { days = 30, granularity = "day" } = params;
272→	const d = Number(days);
273→
274→	let dateGrouping = "toDate(session_date)";
275→	if (granularity === "week") {
276→		dateGrouping = "toMonday(session_date)";
277→	} else if (granularity === "month") {
278→		dateGrouping = "toStartOfMonth(session_date)";
279→	}
280→
281→	const query = `
282→    WITH project_key AS (
283→      SELECT if(git_remote != '', git_remote, if(package_name != '', package_name, project_path)) as pk, any(project_path) as project_path
284→      FROM rudel.session_analytics
285→      WHERE project_path = {projectPath:String}
286→        AND (git_remote != '' OR package_name != '' OR project_path != '')
287→        AND organization_id = {orgId:String}
288→      LIMIT 1
289→    )
290→    SELECT
291→      toString(${dateGrouping}) as date,
292→      pk.project_path,
293→      COUNT(*) as sessions,
294→      COUNT(DISTINCT s.user_id) as unique_users
295→    FROM project_key pk
296→    INNER JOIN rudel.session_analytics s ON if(s.git_remote != '', s.git_remote, if(s.package_name != '', s.package_name, s.project_path)) = pk.pk
297→    WHERE ${buildDateFilter("days", "s.session_date")}
298→      AND s.organization_id = {orgId:String}
299→    GROUP BY ${dateGrouping}, pk.project_path
300→    ORDER BY date ASC
301→  `;
302→
303→	return queryClickhouse<ProjectActivity>({
304→		query,
305→		query_params: {
306→			days: d,
307→			orgId,
308→			projectPath,
309→		},
310→	});
311→}
