314→ * Get project summary statistics
315→ */
316→export async function getProjectSummary(
317→	orgId: string,
318→	days = 30,
319→): Promise<ProjectSummary> {
320→	const d = Number(days);
321→
322→	const query = `
323→    WITH project_stats AS (
324→      SELECT
325→        project_path,
