344→		query,
345→		query_params: {
346→			days: d,
347→			orgId,
348→		},
349→	});
350→	return (
351→		result[0] || {
352→			total_projects: 0,
353→			projects_with_silos: 0,
354→			avg_users_per_project: 0,
355→			most_active_project: "",
356→			most_active_sessions: 0,
357→		}
358→	);
