361→/**
362→ * Get detailed metrics for a specific project
363→ */
364→export async function getProjectDetails(
365→	orgId: string,
366→	projectPath: string,
367→	days = 30,
368→): Promise<ProjectDetails | null> {
369→	const d = Number(days);
370→	const projectDisplaySubquery = buildProjectDisplaySubquery(
371→		"orgId",
372→		"projectPath",
373→	);
374→	const query_params = {
375→		days: d,
376→		orgId,
377→		projectPath,
378→	};
379→
380→	const query = `
381→    SELECT
382→      any(project_path) as raw_project_path,
383→      COUNT(*) as total_sessions,
384→      SUM(ifNull(input_tokens, 0) + ifNull(output_tokens, 0)) as total_tokens,
385→      SUM(ifNull(input_tokens, 0)) as input_tokens_sum,
386→      SUM(ifNull(output_tokens, 0)) as output_tokens_sum,
387→      COUNT(DISTINCT user_id) as contributors_count,
388→      countIf(success_score < 40) as errors_count,
389→      ifNull(round(avgOrNull(actual_duration_min), 2), 0) as avg_session_duration_min,
390→      ifNull(round(avgOrNull(success_score), 2), 0) as success_rate,
391→      round(SUM(actual_duration_min), 2) as total_duration_min
392→    FROM rudel.session_analytics
393→    WHERE ${PROJECT_DISPLAY_EXPR} = ${projectDisplaySubquery}
394→      AND ${buildDateFilter("days")}
395→      AND organization_id = {orgId:String}
396→      AND (git_remote != '' OR package_name != '' OR project_path != '')
397→  `;
398→
399→	let results: (Omit<ProjectDetails, "project_path"> & {
400→		raw_project_path: string;
401→		input_tokens_sum: number;
402→		output_tokens_sum: number;
403→	})[];
404→	try {
405→		results = await queryClickhouse<
406→			Omit<ProjectDetails, "project_path"> & {
407→				raw_project_path: string;
408→				input_tokens_sum: number;
409→				output_tokens_sum: number;
410→			}
411→		>({
412→			query,
413→			query_params,
414→		});
415→	} catch (err) {
416→		logger.error(
417→			"getProjectDetails ClickHouse query failed for org={org} path={path}: {error}",
418→			{ org: orgId, path: projectPath, error: String(err) },
419→		);
420→		throw err;
421→	}
422→
423→	const [row] = results;
424→	if (!row || row.total_sessions === 0) return null;
425→	const cost =
426→		row.output_tokens_sum * 0.000015 + row.input_tokens_sum * 0.000003;
427→	return {
428→		project_path: row.raw_project_path,
429→		total_sessions: row.total_sessions,
430→		total_tokens: row.total_tokens,
431→		contributors_count: row.contributors_count,
432→		errors_count: row.errors_count,
433→		avg_session_duration_min: row.avg_session_duration_min,
434→		success_rate: row.success_rate,
435→		total_duration_min: row.total_duration_min,
436→		cost: parseFloat(cost.toFixed(4)),
437→	};
438→}
