491→/**
492→ * Get feature usage for a specific project
493→ */
494→export async function getProjectFeatureUsage(
495→	orgId: string,
496→	projectPath: string,
497→	days = 30,
498→): Promise<ProjectFeatureUsage> {
499→	const d = Number(days);
500→	const projectDisplaySubquery = buildProjectDisplaySubquery(
501→		"orgId",
502→		"projectPath",
503→	);
504→	const query_params = {
505→		days: d,
506→		orgId,
507→		projectPath,
508→	};
509→
510→	const adoptionQuery = `
511→    SELECT
512→      COUNT(*) as total_sessions,
513→      countIf(length(subagent_types) > 0) as subagents_sessions,
514→      countIf(length(skills) > 0) as skills_sessions,
515→      countIf(length(slash_commands) > 0) as slash_commands_sessions
516→    FROM rudel.session_analytics
517→    WHERE ${PROJECT_DISPLAY_EXPR} = ${projectDisplaySubquery}
518→      AND ${buildDateFilter("days")}
519→      AND organization_id = {orgId:String}
520→      AND (git_remote != '' OR package_name != '' OR project_path != '')
521→  `;
522→
523→	const topSubagentsQuery = `
524→    SELECT val as name, count() as count
525→    FROM rudel.session_analytics
526→    ARRAY JOIN subagent_types as val
527→    WHERE ${PROJECT_DISPLAY_EXPR} = ${projectDisplaySubquery}
528→      AND ${buildDateFilter("days")}
529→      AND organization_id = {orgId:String}
530→      AND (git_remote != '' OR package_name != '' OR project_path != '')
531→      AND val != ''
532→    GROUP BY val
533→    ORDER BY count DESC
534→    LIMIT 10
535→  `;
536→
537→	const topSkillsQuery = `
538→    SELECT val as name, count() as count
539→    FROM rudel.session_analytics
540→    ARRAY JOIN skills as val
541→    WHERE ${PROJECT_DISPLAY_EXPR} = ${projectDisplaySubquery}
542→      AND ${buildDateFilter("days")}
543→      AND organization_id = {orgId:String}
544→      AND (git_remote != '' OR package_name != '' OR project_path != '')
545→      AND val != ''
546→    GROUP BY val
547→    ORDER BY count DESC
548→    LIMIT 10
549→  `;
550→
551→	const topSlashCommandsQuery = `
552→    SELECT val as name, count() as count
553→    FROM rudel.session_analytics
554→    ARRAY JOIN slash_commands as val
555→    WHERE ${PROJECT_DISPLAY_EXPR} = ${projectDisplaySubquery}
556→      AND ${buildDateFilter("days")}
557→      AND organization_id = {orgId:String}
558→      AND (git_remote != '' OR package_name != '' OR project_path != '')
559→      AND val != ''
560→    GROUP BY val
561→    ORDER BY count DESC
562→    LIMIT 10
563→  `;
564→
565→	const [adoptionResults, topSubagents, topSkills, topSlashCommands] =
566→		await Promise.all([
567→			queryClickhouse<{
568→				total_sessions: number;
569→				subagents_sessions: number;
570→				skills_sessions: number;
571→				slash_commands_sessions: number;
572→			}>({
573→				query: adoptionQuery,
574→				query_params,
575→			}),
576→			queryClickhouse<{ name: string; count: number }>({
577→				query: topSubagentsQuery,
578→				query_params,
579→			}),
580→			queryClickhouse<{ name: string; count: number }>({
581→				query: topSkillsQuery,
582→				query_params,
583→			}),
584→			queryClickhouse<{ name: string; count: number }>({
585→				query: topSlashCommandsQuery,
586→				query_params,
587→			}),
588→		]);
589→
590→	if (adoptionResults.length === 0) {
591→		return {
592→			subagents_adoption_rate: 0,
593→			skills_adoption_rate: 0,
594→			slash_commands_adoption_rate: 0,
595→			top_subagents: [],
596→			top_skills: [],
597→			top_slash_commands: [],
598→		};
599→	}
600→
601→	const [stats] = adoptionResults;
602→	if (!stats)
603→		return {
604→			subagents_adoption_rate: 0,
605→			skills_adoption_rate: 0,
606→			slash_commands_adoption_rate: 0,
607→			top_subagents: [],
608→			top_skills: [],
609→			top_slash_commands: [],
610→		};
611→	return {
612→		subagents_adoption_rate:
613→			stats.total_sessions > 0
614→				? (stats.subagents_sessions / stats.total_sessions) * 100
615→				: 0,
616→		skills_adoption_rate:
617→			stats.total_sessions > 0
618→				? (stats.skills_sessions / stats.total_sessions) * 100
619→				: 0,
620→		slash_commands_adoption_rate:
621→			stats.total_sessions > 0
622→				? (stats.slash_commands_sessions / stats.total_sessions) * 100
623→				: 0,
624→		top_subagents: topSubagents,
625→		top_skills: topSkills,
626→		top_slash_commands: topSlashCommands,
627→	};
628→}
