630→/**
631→ * Get error patterns specific to a project
632→ */
633→export async function getProjectErrors(
634→	orgId: string,
635→	projectPath: string,
636→	days = 30,
637→): Promise<ProjectError[]> {
638→	const d = Number(days);
639→	const projectDisplaySubquery = buildProjectDisplaySubquery(
640→		"orgId",
641→		"projectPath",
642→	);
643→
644→	const query = `
645→    WITH error_extracts AS (
646→      SELECT
647→        session_id,
648→        user_id,
649→        session_date,
650→        CASE
651→          WHEN content LIKE '%OperationFailed%' THEN 'OperationFailed'
652→          WHEN content LIKE '%UnknownError%' THEN 'UnknownError'
653→          WHEN content LIKE '%ORPCError%' THEN 'ORPCError'
654→          WHEN content LIKE '%TimeoutError%' THEN 'TimeoutError'
655→          WHEN content LIKE '%TypeError%' THEN 'TypeError'
656→          WHEN content LIKE '%ReferenceError%' THEN 'ReferenceError'
657→          WHEN content LIKE '%Error:%' OR content LIKE '%error:%' THEN 'GenericError'
658→          ELSE NULL
659→        END as error_pattern
660→      FROM rudel.session_analytics
661→      WHERE ${PROJECT_DISPLAY_EXPR} = ${projectDisplaySubquery}
662→        AND ${buildDateFilter("days")}
663→        AND organization_id = {orgId:String}
664→        AND (git_remote != '' OR package_name != '' OR project_path != '')
665→        AND (content LIKE '%Error:%' OR content LIKE '%error:%')
666→    )
667→    SELECT
668→      error_pattern,
669→      COUNT(*) as occurrences,
670→      uniq(user_id) as affected_users,
671→      toString(min(session_date)) as first_seen,
672→      toString(max(session_date)) as last_seen
673→    FROM error_extracts
674→    WHERE error_pattern IS NOT NULL
675→    GROUP BY error_pattern
676→    ORDER BY occurrences DESC
677→    LIMIT 20
678→  `;
679→
680→	return queryClickhouse<ProjectError>({
681→		query,
682→		query_params: {
683→			days: d,
684→			orgId,
685→			projectPath,
686→		},
687→	});
688→}
