690→/**
691→ * Get project trend data for time series charts (split by project)
692→ */
693→export async function getProjectTrends(
694→	orgId: string,
695→	days = 30,
696→	groupBy: "day" | "week" = "day",
697→): Promise<ProjectTrendDataPoint[]> {
698→	const d = Number(days);
699→
700→	const dateFunc =
701→		groupBy === "week"
702→			? "toMonday(toDate(session_date))"
703→			: "toDate(session_date)";
704→
705→	const query = `
706→    SELECT
707→      toString(${dateFunc}) as date,
708→      ${PROJECT_DISPLAY_EXPR} as project_key,
709→      any(project_path) as _project_path,
710→      COUNT(*) as sessions,
711→      round(SUM(actual_duration_min) / 60, 2) as total_hours,
712→      SUM(ifNull(input_tokens, 0) + ifNull(output_tokens, 0)) as total_tokens,
713→      round(AVG(success_score), 2) as avg_success_rate
714→    FROM rudel.session_analytics
715→    WHERE ${buildDateFilter("days")}
716→      AND organization_id = {orgId:String}
717→      AND (git_remote != '' OR package_name != '' OR project_path != '')
718→    GROUP BY date, ${PROJECT_DISPLAY_EXPR}
719→    ORDER BY date ASC, project_key ASC
720→  `;
721→
722→	const results = await queryClickhouse<
723→		ProjectTrendDataPoint & { project_key: string; _project_path: string }
724→	>({
725→		query,
726→		query_params: {
727→			days: d,
728→			orgId,
729→		},
730→	});
731→
732→	return results.map((item) => ({
733→		date: item.date,
734→		project_path: item._project_path,
735→		project_name: item.project_key,
736→		sessions: item.sessions,
737→		total_hours: item.total_hours,
738→		total_tokens: item.total_tokens,
739→		avg_success_rate: item.avg_success_rate,
740→	}));
741→}
