  1→import { createClient } from "@clickhouse/client-web";
  2→import { getLogger } from "@logtape/logtape";
  3→
  4→const logger = getLogger(["rudel", "api", "clickhouse"]);
  5→
  6→const ALLOWED_CLICKHOUSE_TABLES = new Set([
  7→	"rudel.claude_sessions",
  8→	"rudel.codex_sessions",
  9→	"rudel.session_analytics",
 10→]);
 11→
 12→export interface ClickHouseStatement {
 13→	query: string;
 14→	query_params?: Record<string, unknown>;
 15→	format?: "JSONEachRow";
 16→}
 17→
 18→export interface ClickHouseExecutor {
 19→	execute(statement: ClickHouseStatement): Promise<void>;
 20→	query<T>(statement: ClickHouseStatement): Promise<T[]>;
 21→	insert(params: { table: string; values: object[] }): Promise<void>;
 22→}
 23→
 24→export function getSafeClickHouseTable(table: string): string {
 25→	if (!ALLOWED_CLICKHOUSE_TABLES.has(table)) {
 26→		throw new Error(`Unsupported ClickHouse table: ${table}`);
 27→	}
 28→	return table;
 29→}
 30→
 31→export function createClickHouseExecutor(config: {
 32→	url: string;
 33→	username?: string;
 34→	password?: string;
 35→	database?: string;
 36→}): ClickHouseExecutor {
 37→	const client = createClient({
 38→		url: config.url,
 39→		username: config.username,
 40→		password: config.password,
 41→		database: config.database,
 42→		request_timeout: 120_000,
 43→		clickhouse_settings: {
 44→			wait_end_of_query: 1,
 45→			output_format_json_quote_64bit_integers: 0,
 46→		},
 47→	});
 48→	return {
 49→		async execute(statement: ClickHouseStatement) {
 50→			await client.command({
 51→				query: statement.query,
 52→				query_params: statement.query_params,
 53→			});
 54→		},
 55→		async query<T>(statement: ClickHouseStatement): Promise<T[]> {
 56→			const result = await client.query({
 57→				query: statement.query,
 58→				query_params: statement.query_params,
 59→				format: statement.format ?? "JSONEachRow",
 60→			});
 61→			return result.json();
 62→		},
 63→		async insert(params) {
 64→			const table = getSafeClickHouseTable(params.table);
 65→			// Use command() with FORMAT JSONEachRow instead of client.insert()
 66→			// because ClickHouse Cloud's @clickhouse/client insert() silently drops data.
 67→			const rows = params.values.map((r) => JSON.stringify(r)).join("\n");
 68→			await client.command({
 69→				query: `INSERT INTO ${table} SETTINGS async_insert=0 FORMAT JSONEachRow ${rows}`,
 70→			});
 71→		},
 72→	};
 73→}
 74→
 75→let _clickhouse: ClickHouseExecutor | null = null;
 76→
 77→export function getClickhouse(): ClickHouseExecutor {
 78→	if (!_clickhouse) {
 79→		const executor = createClickHouseExecutor({
 80→			url: process.env.CLICKHOUSE_URL || "http://localhost:8123",
 81→			username:
 82→				process.env.CLICKHOUSE_USERNAME ||
 83→				process.env.CLICKHOUSE_USER ||
 84→				"default",
 85→			password: process.env.CLICKHOUSE_PASSWORD || "",
 86→			database: "default",
 87→		});
 88→		const maxRetries = 3;
 89→		_clickhouse = {
 90→			...executor,
 91→			async insert(params) {
 92→				for (let attempt = 0; attempt < maxRetries; attempt++) {
 93→					try {
 94→						return await executor.insert(params);
 95→					} catch (error) {
 96→						if (attempt === maxRetries - 1) {
 97→							logger.error(
 98→								"Insert into {table} failed after {maxRetries} attempts: {error}",
 99→								{ table: params.table, maxRetries, error },
100→							);
101→							throw error;
102→						}
103→						logger.warn(
104→							"Insert into {table} failed (attempt {attempt}/{maxRetries}), retrying: {error}",
105→							{
106→								table: params.table,
107→								attempt: attempt + 1,
108→								maxRetries,
109→								error,
110→							},
111→						);
112→						await new Promise((r) => setTimeout(r, 100 * (attempt + 1)));
113→					}
114→				}
115→			},
116→		};
117→	}
118→	return _clickhouse;
119→}
