121→export function addOptionalStringEqFilter(
122→	where: string[],
123→	query_params: Record<string, unknown>,
124→	column: string,
125→	paramName: string,
126→	value?: string,
127→): void {
128→	if (!value) return;
129→	where.push(`${column} = {${paramName}:String}`);
130→	query_params[paramName] = value;
131→}
132→
133→export function addOptionalStringInFilter(
134→	where: string[],
135→	query_params: Record<string, unknown>,
136→	column: string,
137→	paramBase: string,
138→	values?: string[],
139→): void {
140→	if (!values || values.length === 0) return;
141→	const placeholders = values.map((value, index) => {
142→		const paramName = `${paramBase}_${index}`;
143→		query_params[paramName] = value;
144→		return `{${paramName}:String}`;
145→	});
146→	where.push(`${column} IN (${placeholders.join(", ")})`);
147→}
148→
149→export function buildDateFilter(
150→	paramName: string,
151→	column = "session_date",
152→): string {
153→	return `${column} >= now64(3) - toIntervalDay({${paramName}:UInt32}) AND ${column} <= now64(3)`;
154→}
155→
156→export function buildAbsoluteDateFilter(
157→	startParamName: string,
158→	endParamName: string,
159→	column = "session_date",
160→): string {
161→	return `toDate(${column}) >= toDate({${startParamName}:String}) AND toDate(${column}) <= toDate({${endParamName}:String})`;
162→}
163→
164→export async function queryClickhouse<T>(
165→	statement: ClickHouseStatement,
166→): Promise<T[]> {
167→	const ch = getClickhouse();
168→	return ch.query<T>(statement);
169→}
