 1→import { getLogger } from "@logtape/logtape";
 2→import { ORPCError } from "@orpc/server";
 3→import type { ClickHouseStatement } from "./clickhouse.js";
 4→import { queryClickhouse } from "./clickhouse.js";
 5→
 6→const logger = getLogger(["rudel", "api", "rate-limit"]);
 7→
 8→export interface RateLimitConfig {
 9→	maxRequests: number;
10→	windowSeconds: number;
11→	countQuery: (userId: string, windowSeconds: number) => ClickHouseStatement;
12→}
13→
14→const ingestCountQuery = (
15→	userId: string,
16→	windowSeconds: number,
17→): ClickHouseStatement => ({
18→	query:
19→		`SELECT sum(c) AS count FROM (` +
20→		`SELECT count() AS c FROM rudel.claude_sessions WHERE user_id = {userId:String} AND ingested_at >= now64(3) - INTERVAL {window:UInt32} SECOND ` +
21→		`UNION ALL ` +
22→		`SELECT count() AS c FROM rudel.codex_sessions WHERE user_id = {userId:String} AND ingested_at >= now64(3) - INTERVAL {window:UInt32} SECOND` +
23→		`)`,
24→	query_params: { userId, window: windowSeconds },
25→});
26→
27→export const INGEST_RATE_LIMIT: RateLimitConfig = {
28→	maxRequests: Number(process.env.RATE_LIMIT_INGEST_MAX ?? 120),
29→	windowSeconds: Number(process.env.RATE_LIMIT_INGEST_WINDOW ?? 3600),
30→	countQuery: ingestCountQuery,
31→};
32→
33→/**
34→ * Checks if a user has exceeded their rate limit.
35→ * Returns the current count, or null if the check failed (ClickHouse down).
36→ */
37→export async function checkIngestRateLimit(
38→	userId: string,
39→	config: RateLimitConfig = INGEST_RATE_LIMIT,
40→): Promise<void> {
41→	const { maxRequests, windowSeconds, countQuery } = config;
42→
43→	try {
44→		const rows = await queryClickhouse<{ count: number }>(
45→			countQuery(userId, windowSeconds),
46→		);
47→		const count = rows[0]?.count ?? 0;
48→
49→		if (count >= maxRequests) {
50→			logger.warn(
51→				"Rate limit exceeded for user {userId}: {count}/{maxRequests} in {windowSeconds}s",
52→				{ userId, count, maxRequests, windowSeconds },
53→			);
54→			throw new ORPCError("TOO_MANY_REQUESTS", {
55→				message: `Rate limit exceeded. Maximum ${maxRequests} requests per ${Math.round(windowSeconds / 60)} minutes.`,
56→			});
57→		}
58→	} catch (error) {
59→		if (error instanceof ORPCError) throw error;
60→		// If ClickHouse is down, log and allow the request through.
61→		// Availability > rate limiting.
62→		logger.error("Rate limit check failed, allowing request: {error}", {
63→			error,
64→		});
65→	}
66→}
