 1→import { implement, ORPCError } from "@orpc/server";
 2→import { contract } from "@rudel/api-routes";
 3→import { member } from "@rudel/sql-schema";
 4→import { and, eq } from "drizzle-orm";
 5→import type { Session } from "./auth.js";
 6→import { db } from "./db.js";
 7→import { checkAnalyticsRateLimit } from "./rate-limit.js";
 8→
 9→export interface AppContext {
10→	user: Session["user"] | null;
11→	session: Session["session"] | null;
12→	apiKeyId: string | null;
13→}
14→
15→export const os = implement(contract).$context<AppContext>();
16→
17→export const authMiddleware = os.middleware(async ({ context, next }) => {
18→	if (!context.user || !context.session) {
19→		throw new ORPCError("UNAUTHORIZED");
20→	}
21→	return next({
22→		context: {
23→			user: context.user,
24→			session: context.session,
25→			apiKeyId: context.apiKeyId,
26→		},
27→	});
28→});
29→
30→export const orgMiddleware = os.middleware(async ({ context, next }) => {
31→	if (!context.user || !context.session) {
32→		throw new ORPCError("UNAUTHORIZED");
33→	}
34→
35→	checkAnalyticsRateLimit(context.user.id);
36→	const organizationId =
37→		(context.session as Record<string, unknown>).activeOrganizationId ??
38→		context.user.id;
39→	if (!organizationId || typeof organizationId !== "string") {
40→		throw new ORPCError("BAD_REQUEST", {
41→			message: "No active organization",
42→		});
43→	}
44→
45→	const membership = await db
46→		.select({ id: member.id, role: member.role })
47→		.from(member)
48→		.where(
49→			and(
50→				eq(member.organizationId, organizationId),
51→				eq(member.userId, context.user.id),
52→			),
53→		)
54→		.limit(1);
55→
56→	const row = membership[0];
57→	if (!row) {
58→		throw new ORPCError("FORBIDDEN", {
59→			message: "Not a member of the active organization",
60→		});
61→	}
62→
63→	const userRole = (row.role as "owner" | "admin" | "member") ?? "member";
64→	const isOrgAdmin = userRole === "owner" || userRole === "admin";
65→
66→	return next({
67→		context: {
68→			user: context.user,
69→			session: context.session,
70→			apiKeyId: context.apiKeyId,
71→			organizationId,
72→			userRole,
73→			isOrgAdmin,
74→		},
75→	});
76→});
77→
78→export const ingestAuthMiddleware = os.middleware(async ({ context, next }) => {
79→	if (!context.user) {
80→		throw new ORPCError("UNAUTHORIZED");
81→	}
82→
83→	if (!context.session && !context.apiKeyId) {
84→		throw new ORPCError("UNAUTHORIZED");
85→	}
86→
87→	return next({
88→		context: {
89→			user: context.user,
90→			session: context.session,
91→			apiKeyId: context.apiKeyId,
92→		},
93→	});
94→});
