45→			days: input.days,
46→		});
47→	});
48→
49→const dimensionAnalysis = os.analytics.sessions.dimensionAnalysis
50→	.use(orgMiddleware)
51→	.handler(async ({ input, context }) => {
52→		return getSessionDimensionAnalysis(context.organizationId, {
53→			days: input.days,
54→			dimension: input.dimension,
55→			metric: input.metric,
56→			split_by: input.splitBy,
57→			limit: input.limit,
58→			user_id: input.userId,
59→			project_path: input.projectPath,
60→		});
61→	});
62→
63→const detail = os.analytics.sessions.detail
64→	.use(orgMiddleware)
65→	.handler(async ({ input, context }) => {
66→		const result = await getSessionDetail(
67→			context.organizationId,
68→			input.sessionId,
69→		);
70→		if (!result) {
71→			throw new ORPCError("NOT_FOUND");
72→		}
73→
74→		// Non-admin members can only view their own sessions
75→		if (!context.isOrgAdmin && result.user_id !== context.user.id) {
76→			throw new ORPCError("FORBIDDEN", {
77→				message: "You can only view your own sessions",
78→			});
79→		}
80→
81→		return result;
82→	});
